"""WMS-418 independent DB + WB readback using pre-operation manifest on stdin."""
import asyncio,collections,json,sys,uuid
from datetime import datetime,UTC
import httpx
from sqlalchemy import text
from app.db.session import SessionLocal
from app.services.fbs_stock_sync_service import _resolve_marketplace_api_token
from app.services.wildberries_client import fetch_marketplace_stocks
T=uuid.UUID('7b98a8aa-c03c-4649-9677-a645be45c622'); S=uuid.UUID('9819f2c6-b28e-401e-a163-6ffe9e420da6')
async def main():
 manifest=MANIFEST
 grouped=collections.defaultdict(set)
 for x in manifest: grouped[x['wb_warehouse_id']].add(x['chrt_id'])
 assert set(grouped)=={2046998,2088990,2157282}
 async with SessionLocal() as s:
  await s.execute(text('SET TRANSACTION READ ONLY'))
  summary=dict((await s.execute(text('SELECT count(*) total,count(*) FILTER(WHERE fbs_stock_sync_enabled) wb_on,count(*) FILTER(WHERE coalesce(fbs_ozon_stock_sync_enabled,fbs_stock_sync_enabled)) ozon_on FROM products WHERE tenant_id=:t AND seller_id=:s'),{'t':T,'s':S})).mappings().one())
  assert summary=={'total':158,'wb_on':0,'ozon_on':0},summary
  token=await _resolve_marketplace_api_token(s,T,S)
  await s.rollback()
 checks=[]
 async with httpx.AsyncClient() as client:
  for wh,ids in sorted(grouped.items()):
   rows=await fetch_marketplace_stocks(client,api_token=token,warehouse_id=wh,chrt_ids=sorted(ids))
   amounts={x.chrt_id:x.amount for x in rows}
   result={'warehouse':wh,'checked':len(ids),'missing':[x for x in ids if x not in amounts],'nonzero':{x:amounts[x] for x in ids if x in amounts and amounts[x]!=0}}
   checks.append(result); print(json.dumps(result),flush=True)
 print(json.dumps({'checked_at':datetime.now(UTC).isoformat(),'summary':summary,'checked_items':sum(len(v) for v in grouped.values()),'pass':all(not x['missing'] and not x['nonzero'] for x in checks)}),flush=True)
 assert all(not x['missing'] and not x['nonzero'] for x in checks)
